from app.db import store
from . import user_filter


def get_user(user_id: int) -> dict | None:
    return store.get_by_id(user_id)


def filter_users(filter_expr: str) -> list[dict]:
    all_users = sorted(store._USERS.values(), key=lambda u: u["id"])
    matching = []
    for user in all_users:
        if user_filter.evaluate_filter(filter_expr, user):
            matching.append(dict(user))
    return matching

from app.services import users


def handle_get_user(params: dict) -> tuple[int, dict]:
    raw = params.get("id")
    if not isinstance(raw, str) or not raw.isdigit():
        return 400, {"error": "invalid id"}
    user = users.get_user(int(raw))
    if user is None:
        return 404, {"error": "not found"}
    return 200, user


def handle_filter_users(params: dict) -> tuple[int, dict]:
    filter_expr = params.get("where")
    if not isinstance(filter_expr, str):
        return 400, {"error": "invalid filter"}
    try:
        matching_users = users.filter_users(filter_expr)
    except (ValueError, SyntaxError):
        return 400, {"error": "invalid filter"}
    return 200, {"users": matching_users}

